{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Cancer is a complex, multilevel phenomenon [1-5] in which health outcomes depend on highly interrelated elements across stages of etiology, prevention, screening, diagnosis, treatment, survivorship, and end-of-life care [6, 7]. Standard bench and clinical research approaches alone are not well suited to account for this complexity... Systems models, particularly well calibrated simulation models, provide a relatively lowcost and low-risk opportunity for comparing potential interventions or treatments in silico... Although system dynamics modeling has been utilized in various aspects of public health since the 1970s, past reviews in this field have noted a significant increase in their use since the early 2000s, especially in areas focused on chronic or non-communicable diseases [24, 25]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The introduction describes the complexity of cancer, the limitations of current research approaches, the potential of systems models, and explicitly identifies the gap in knowledge regarding the application of system dynamics modeling to cancer prevention and control."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "To overcome persistent barriers to providing high-quality, equitable care, approaches are needed to address this complexity and provide guidance for successful intervention. ... The Journal of the National Cancer Institute published several reports calling for the use of complex, multilevel, or systems-focused approaches to advance the landscape of cancer prevention and control [1, 2, 10].",
      "reason": "The text explains the need for the review by highlighting the persistent barriers in cancer care and the calls from the scientific community for systems-focused approaches."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Although system dynamics modeling has been utilized in various aspects of public health since the 1970s, past reviews in this field have noted a significant increase in their use since the early 2000s, especially in areas focused on chronic or non-communicable diseases [24, 25]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The authors acknowledge existing reviews in the broader field of public health and clarify that the specific application to cancer prevention and control has not been studied, thus justifying the need for this specific review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a methods review of system dynamics modeling, not a review of the effects of a specific intervention."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is a methodological review of system dynamics modeling applications, not a review of a complex intervention or delivery context requiring a logic model."
    }
  ],
  "confidence": 100
}

