{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Included articles: 1) were published in peer-reviewed journals; 2) were written in English; 3) used system dynamics modeling (i.e., causal-loop diagramming, stock-and-flow diagramming, or computational system dynamics modeling); 4) pertained to cancer prevention or control; and 4) were published within the last 10 years.",
      "reason": "The authors explicitly list the inclusion criteria for the studies, covering publication type, language, methodology (system dynamics modeling), topic (cancer prevention or control), and publication date range."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Included articles: 1) were published in peer-reviewed journals; 2) were written in English; ... and 4) were published within the last 10 years.",
      "reason": "The authors specify report characteristics including publication status (peer-reviewed journals), language (English), and dissemination year (last 10 years)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is a methods review and does not assess health outcomes in a way that requires distinguishing between exclusion due to outcomes not measured versus not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "As shown in Fig 1, most studies included a computational system dynamics simulation model (n = 21; 66%), while the remaining studies (n = 11; 34%) used only diagramming approaches (referred to as diagram-only studies in this review).",
      "reason": "The authors specify how studies were grouped for synthesis (simulation vs. diagram-only) and this grouping is used throughout the results and analysis (e.g., Fig 6, Fig 3, Fig 4)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "In bounding our review to studies published in the last 10 years, we excluded older studies that could have contributed to this synthesis. We also excluded studies related to topics such as nutrition and physical activity if they did not include cancer in their models or research aims. ... Due to our focus on cancer prevention and control, we also excluded studies that were solely related to cancer pathogenesis",
      "reason": "The authors provide rationales for specific restrictions, such as the 10-year publication window and the exclusion of studies focused solely on cancer pathogenesis."
    }
  ],
  "confidence": 100
}

